// GENERATED by scripts/sync-shared.mjs from hotel-clash-api/engine — do not edit here.
// One in-game day. Ported from the game loop in pages/game.js; the order of
// operations matches the original. Differences from the old client code are
// marked "FIX:" — they are bugs that only existed because React state updates
// were computed from stale snapshots.
import { dpow, pick } from './math.js';
import { clamp, seasonFor } from './core.js';
import {
  ROOM_TYPES,
  FACILITY_TYPES,
  FIRST_NAMES,
  LAST_NAMES,
  ACHIEVEMENTS,
  LEVELS,
  DAILY_CHALLENGES,
  DEBT,
  CAMPAIGNS,
  ROOM_WEAR_PER_DAY,
  NEW_RIVAL_NAMES,
} from './data.js';
import { triggerRandomEvent, maintenanceEvent } from './events.js';
import { dailyCosts, roomPricePoint, priceThreshold, guestExpectation, debtBookingPenalty, repoTarget, evaluateChallenge, facilityOffer, facilityCapacity, visitChance, localDemand, marketingDemand, profitTax, hotelValue, levelForValue, unlocksAt, staffing } from './insights.js';

const fmt = (n) => Math.round(n).toLocaleString('en-US');

export function runDay(G) {
  const { S } = G;
  S.day += 1;

  const startReputation = S.reputation;
  const revenue = dailyFinances(G);
  // FIX: judge the challenge before resetting the day's maintenance spend
  // (the reset used to come first, so the Eco challenge was always won).
  checkDailyChallenge(G, revenue, startReputation);
  S.stats.maintenanceToday = 0;
  guestDepartures(G);
  generateNewGuests(G);
  updateRoomStatus(G);
  updateStaffStatus(G);
  updateMarketingCampaigns(G);
  updateCompetitors(G);
  calculateMarketShare(G);
  checkBankruptcy(G);
  triggerRandomEvent(G);
  newDailyChallenge(G);

  if (S.day > 100 && S.day % 7 === 0) {
    // FIX: a weekly check popped a game-pausing event window every ~21 s of
    // play. It's routine: report it in the log instead.
    const result = maintenanceEvent(G);
    G.notify(`🔧 Weekly maintenance: ${result}`, false, 'maintenance');
  }
}

// ---------------------------------------------------------------- finances

function dailyFinances(G) {
  const { S, rand } = G;
  const costs = dailyCosts(S);
  const roomIncome = S.rooms.reduce((t, r) => t + (r.occupied ? r.price : 0), 0);

  // Facilities: hotel guests first, then walk-ins from town, up to the seats
  // available. Each visitor orders from the menu (or pays the entry fee).
  let facilityIncome = 0;
  let facilityCogs = 0;
  const facilityStats = {};
  for (const f of S.facilities) {
    if (f.name === 'Lobby') continue;
    const offer = facilityOffer(f);
    const capacity = facilityCapacity(S, f);
    const day = { visitors: 0, guests: 0, locals: 0, turnedAway: 0, revenue: 0, cogs: 0 };
    const serve = () => {
      day.visitors++;
      for (let k = 0; k < offer.orders; k++) {
        const item = offer.items[Math.floor(rand() * offer.items.length)];
        day.revenue += item.price;
        day.cogs += item.cost;
      }
    };
    for (const guest of S.guests) {
      if (rand() >= visitChance(S, f, guest.type, offer)) continue;
      if (day.visitors < capacity) {
        day.guests++;
        serve();
      } else day.turnedAway++;
    }
    const walkIns = Math.floor(localDemand(S, f, offer, capacity) + rand());
    for (let i = 0; i < walkIns; i++) {
      if (day.visitors < capacity) {
        day.locals++;
        serve();
      } else day.turnedAway++;
    }
    facilityStats[f.id] = day;
    facilityIncome += day.revenue;
    facilityCogs += day.cogs;
  }

  const revenue = roomIncome + facilityIncome;
  const beforeTax = revenue - costs.total - facilityCogs;
  const tax = beforeTax > 0 ? profitTax(beforeTax) : 0;
  const profit = beforeTax - tax;
  S.money += profit;
  // Smoothed profit (one bad event day shouldn't wipe out away earnings)
  S.stats.avgDayProfit = Math.round(typeof S.stats.avgDayProfit === 'number' ? S.stats.avgDayProfit * 0.9 + profit * 0.1 : profit);
  S.stats.lastDayTax = tax;
  S.stats.lastDayRevenue = revenue;
  S.stats.lastDayRoomIncome = roomIncome;
  S.stats.lastDayFacilityIncome = facilityIncome;
  S.stats.lastDayFacilityCogs = facilityCogs;
  S.stats.facilities = facilityStats;

  const isCritical = S.money < 1000 && S.money >= 0;
  // FIX: debt has its own warnings (checkBankruptcy); this used to say "$-4,626 remaining".
  const isLow = S.money < 5000 && S.money >= 1000;
  if ((isLow && S.day % 3 === 0) || isCritical) {
    G.emit({ kind: 'lowBalance', critical: isCritical, money: S.money });
    G.notify(
      isCritical
        ? `⚠️ CRITICAL: Balance at $${fmt(S.money)}! 💎 Buy Credits NOW to avoid bankruptcy!`
        : `💰 Low Balance Warning: $${fmt(S.money)} remaining. 💎 Consider buying Credits to expand your hotel!`,
      true,
      isCritical ? 'urgent' : 'warning'
    );
  }
  return revenue;
}

// ---------------------------------------------------------------- guests

